<span class="line"><span style="--shiki-light:#998418;--shiki-dark:#B8A965;">    max-threads</span><span style="--shiki-light:#999999;--shiki-dark:#666666;">:</span><span style="--shiki-light:#2F798A;--shiki-dark:#4C9A91;"> 200</span><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"> #最大线程数</span></span>
